/* ==========================================================================
 *  Exports
 * ========================================================================== */
const PRESET_RACE_TEMPLATES = [
  XIANXIA_RACES,
  WARCRAFT_RACES,
  PREHISTORIC_RACES,
  ISEKAI_RACES,
  DND_RACES,
]

export default PRESET_RACE_TEMPLATES

/** 快速获取模板列表（供下拉选择） */
export function getRaceTemplateList() {
  return PRESET_RACE_TEMPLATES.map((t) => ({
    key: t.templateKey,
    name: t.templateName,
    icon: t.templateIcon,
    tags: t.templateTags,
    desc: t.templateDesc,
    raceCount: t.races.length,
  }))
}

/** 按 key 获取模板完整数据 */
export function getRaceTemplateByKey(key) {
  return PRESET_RACE_TEMPLATES.find((t) => t.templateKey === key) || null
}

/** 返回模板 key → 名称的映射 */
export function getRaceTemplateMap() {
  return Object.fromEntries(
    PRESET_RACE_TEMPLATES.map((t) => [t.templateKey, { name: t.templateName, icon: t.templateIcon }])
  )
}
